// =======================================
// ENVIAR PARA LLM - PAYLOAD COMPLETO
// Repassa TODO o webhook sem perder nada
// =======================================

const data = $json;

// Payload completo para o webhook de atendimento LLM
return [{
  json: {
    // =============================
    // IDENTIFICADORES
    // =============================
    message_id: data.message_id,
    conversation_id: data.conversation_id,
    contact_lid: data.contact_lid,
    chat_lid: data.chat_lid,
    participant_lid: data.participant_lid,
    phone: data.phone,
    connected_phone: data.connected_phone,

    // =============================
    // CLASSIFICAÇÃO
    // =============================
    tipo_evento: data.tipo_evento,
    event_type: data.event_type,
    operation: data.operation,

    // =============================
    // DIREÇÃO E ORIGEM
    // =============================
    direction: data.direction,
    origin: data.origin,
    from_me: data.from_me,
    from_api: data.from_api,

    // =============================
    // CONTEXTO BOOLEAN
    // =============================
    is_group: data.is_group,
    is_status_reply: data.is_status_reply,
    is_edit: data.is_edit,
    is_newsletter: data.is_newsletter,
    waiting_message: data.waiting_message,
    is_forwarded: data.is_forwarded,
    broadcast: data.broadcast,

    // =============================
    // CONTEÚDO
    // =============================
    message_text: data.message_text,
    caption: data.caption,
    media_type: data.media_type,
    media_url: data.media_url,
    mime_type: data.mime_type,
    file_name: data.file_name,

    // =============================
    // DADOS DO CONTATO
    // =============================
    chat_name: data.chat_name,
    sender_name: data.sender_name,
    sender_photo: data.sender_photo,
    push_name: data.push_name,
    notify_name: data.notify_name,

    // =============================
    // STATUS
    // =============================
    status: data.status,
    sent_at: data.sent_at,
    delivered_at: data.delivered_at,
    read_at: data.read_at,

    // =============================
    // TIMESTAMPS
    // =============================
    first_event_at: data.first_event_at,
    last_update_at: data.last_update_at,
    data_timestamp: data.data_timestamp,

    // =============================
    // REPLY/QUOTE
    // =============================
    quoted_msg_id: data.quoted_msg_id,
    quoted_msg_body: data.quoted_msg_body,
    quoted_msg: data.quoted_msg,

    // =============================
    // REAÇÃO
    // =============================
    reaction_text: data.reaction_text,
    reaction_message_id: data.reaction_message_id,

    // =============================
    // INTERACTIVE
    // =============================
    selected_button_id: data.selected_button_id,
    selected_row_id: data.selected_row_id,
    buttons_response: data.buttons_response,
    list_response: data.list_response,

    // =============================
    // POLL
    // =============================
    poll_name: data.poll_name,
    poll_options: data.poll_options,

    // =============================
    // INFRA
    // =============================
    instance_id: data.instance_id,
    phone_device: data.phone_device,
    ids_array: data.ids_array,

    // =============================
    // DEBUG
    // =============================
    trace_id: data.trace_id,
    span_id: data.span_id,

    // =============================
    // AUDITORIA
    // =============================
    raw_payload: data.raw_payload,
    raw_zapi: data.raw_zapi
  }
}];

// =======================================
// PROCESSAR EVENTO — v2 PADRÃO LABONCHAIN
// =======================================

const httpInput = $json ?? {};
const rawZapi = httpInput.body ?? {};

/* ================= TIMEZONE ================= */

function toSP(ms) {
  if (!ms) return null;

  try {
    return new Date(
      new Date(ms).toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' })
    ).toISOString().replace('Z', '-03:00');
  } catch {
    return null;
  }
}

const nowSP = toSP(Date.now());
const eventAt = rawZapi.momment ? toSP(rawZapi.momment) : nowSP;

/* ================= MESSAGE ID ================= */

const messageId =
  rawZapi.messageId ??
  rawZapi.message_id ??
  rawZapi.ids?.[0] ??
  null;

if (!messageId) {
  return [];
}

const traceId = rawZapi._traceContext?.traceId ?? null;
const spanId  = rawZapi._traceContext?.spanId  ?? null;

/* ================= IDENTIFICAÇÃO ================= */

const chatLid = rawZapi.chatLid ?? rawZapi.chat_lid ?? null;
const senderLid = rawZapi.senderLid ?? null;
const participantLid = rawZapi.participantLid ?? rawZapi.participant_lid ?? null;
const participantPhone = rawZapi.participantPhone ?? null;
const phone = rawZapi.phone ?? null;
const connectedPhone = rawZapi.connectedPhone ?? rawZapi.connected_phone ?? null;
const eventType = rawZapi.type ?? rawZapi.event_type ?? null;
if (eventType === 'MessageStatusCallback' || eventType === 'DeliveryCallback') {
  return [{
    json: {
      _redirect: 'status',
      message_id: rawZapi.ids?.[0] ?? rawZapi.messageId ?? rawZapi.id ?? null,
      phone: rawZapi.phone ?? null,
      instance_id: rawZapi.instanceId ?? null,
      is_group: rawZapi.isGroup ?? false,
      status: rawZapi.status ?? null,
      momment: rawZapi.momment ?? null,
      raw_payload: JSON.stringify($json),
    }
  }];
}
const fromMe = rawZapi.fromMe ?? rawZapi.from_me ?? false;
const isGroup = rawZapi.isGroup ?? rawZapi.is_group ?? false;
const direction = fromMe ? 'OUTBOUND' : 'INBOUND';
const isIncoming = eventType === 'ReceivedCallback';
const notification = rawZapi.notification ?? null;
const isGroupNotification = isGroup && notification !== null;
const notificationParams = rawZapi.notificationParameters
  ? JSON.stringify(rawZapi.notificationParameters)
  : null;

const notificationContactLid = rawZapi.notificationParameters?.[0] ?? null;

/* ================= IDs CORRIGIDOS POR CONTEXTO ================= */

const conversationId = isGroup
  ? (phone ?? null)                             // grupo: phone é o ID do grupo ex: 120363...@g.us
  : (chatLid ?? phone ?? null);                 // privada: chatLid ou phone

const contactLid = isGroup
  ? (participantLid ?? participantPhone ?? null) // grupo: quem enviou a msg
  : (chatLid ?? phone ?? null);                 // privada: chatLid ou phone

/* ================= OPERATION ================= */

let operation = 'CREATE';

if (rawZapi.status && rawZapi.status !== 'RECEIVED') {
  operation = 'UPDATE';
}

/* ================= TEXTO ================= */

const messageText =
  rawZapi.text?.message ??
  rawZapi.message_text ??
  rawZapi.hydratedTemplate?.message ??
  rawZapi.listMessage?.description ??
  rawZapi.buttonsMessage?.message ??
  rawZapi.interactiveMessage?.body ??
  null;

/* ================= MÍDIA ================= */

let mediaType     = null;
let mediaUrl      = null;
let mimeType      = null;
let fileName      = null;
let caption       = null;
let ptt           = null;
let audioDuration = null;
let pageCount     = null;
let thumbnailUrl  = null;

if (rawZapi.image) {
  mediaType    = 'image';
  mediaUrl     = rawZapi.image?.imageUrl     ?? null;
  mimeType     = rawZapi.image?.mimeType     ?? null;
  caption      = rawZapi.image?.caption      ?? null;
  thumbnailUrl = rawZapi.image?.thumbnailUrl ?? null;
}

else if (rawZapi.video) {
  mediaType     = 'video';
  mediaUrl      = rawZapi.video?.videoUrl ?? null;
  mimeType      = rawZapi.video?.mimeType ?? null;
  caption       = rawZapi.video?.caption  ?? null;
  audioDuration = rawZapi.video?.seconds  ?? null;
}

else if (rawZapi.audio) {
  mediaType     = 'audio';
  mediaUrl      = rawZapi.audio?.audioUrl ?? null;
  mimeType      = rawZapi.audio?.mimeType ?? null;
  ptt           = rawZapi.audio?.ptt      ?? false;
  audioDuration = rawZapi.audio?.seconds  ?? null;
}

else if (rawZapi.document) {
  mediaType = 'document';
  mediaUrl  = rawZapi.document?.documentUrl ?? null;
  mimeType  = rawZapi.document?.mimeType    ?? null;
  fileName  = rawZapi.document?.fileName    ?? null;
  caption   = rawZapi.document?.caption      ?? null;
  pageCount = rawZapi.document?.pageCount   ?? null;
}

else if (rawZapi.sticker) {
  mediaType = 'sticker';
  mediaUrl  = rawZapi.sticker?.stickerUrl ?? null;
  mimeType  = rawZapi.sticker?.mimeType   ?? null;
}
else if (rawZapi.gif) {
  mediaType = 'gif';
  mediaUrl  = rawZapi.gif?.gifUrl   ?? null;
  mimeType  = rawZapi.gif?.mimeType ?? null;
}
else if (rawZapi.ptv) {
  mediaType = 'ptv';
  mediaUrl  = rawZapi.ptv?.ptvUrl   ?? null;
  mimeType  = rawZapi.ptv?.mimeType ?? null;
}
else if (rawZapi.contact) {
  mediaType = 'contact';
}
else if (rawZapi.location) {
  mediaType = 'location';
}
else if (rawZapi.hydratedTemplate?.header?.document) {
  mediaType = 'document';
  mediaUrl  = rawZapi.hydratedTemplate.header.document.documentUrl ?? null;
  mimeType  = rawZapi.hydratedTemplate.header.document.mimeType    ?? null;
  fileName  = rawZapi.hydratedTemplate.header.document.fileName    ?? null;
  caption   = rawZapi.hydratedTemplate.header.document.caption     ?? null;
}
else if (rawZapi.hydratedTemplate?.header?.image) {
  mediaType = 'image';
  mediaUrl  = rawZapi.hydratedTemplate.header.image.imageUrl ?? null;
  mimeType  = rawZapi.hydratedTemplate.header.image.mimeType ?? null;
  caption   = rawZapi.hydratedTemplate.header.image.caption  ?? null;
}
else if (rawZapi.hydratedTemplate?.header?.video) {
  mediaType = 'video';
  mediaUrl  = rawZapi.hydratedTemplate.header.video.videoUrl ?? null;
  mimeType  = rawZapi.hydratedTemplate.header.video.mimeType ?? null;
}

/* ================= LEAD FIELDS ================= */

// Grupo: dados do participante que enviou
// Privada: dados do contato
const leadPhone = isGroup ? participantPhone : phone;
const leadPhoneDdd = leadPhone ? String(leadPhone).substring(2, 4) : null;
const leadPhoneNumber = leadPhone ? String(leadPhone).substring(4) : null;

function nomeValido(nome, ...identificadores) {
  if (!nome) return false;
  const n = String(nome).trim();
  if (!n) return false;
  return !identificadores.some(id => id && n === String(id).trim());
}

// fromMe:true em chat privado -> senderName é sempre o nome da própria conta conectada
// (ex.: "J S Gráfica"), nunca o nome do cliente. Nao usar como candidato nesse caso -
// causa raiz da demanda 169 (contatos LID-only gravados com o nome da empresa).
const leadName = isGroup
  ? ([rawZapi.senderName, rawZapi.pushName].find(n => nomeValido(n, participantPhone, participantLid)) ?? null)
  : (fromMe
      ? ([rawZapi.chatName].find(n => nomeValido(n, phone, chatLid)) ?? null)
      : ([rawZapi.chatName, rawZapi.senderName].find(n => nomeValido(n, phone, chatLid)) ?? null));

const leadPhoto = isGroup
  ? (rawZapi.senderPhoto ?? null)
  : (rawZapi.senderPhoto ?? rawZapi.photo ?? null);

/* ================= STATUS ================= */

const status = rawZapi.status ?? null;

let sentAt = null;
let deliveredAt = null;
let readAt = null;

if (status === 'SENT') sentAt = eventAt;
if (status === 'DELIVERED') deliveredAt = eventAt;
if (status === 'READ') readAt = eventAt;

/* ================= ROTEAMENTO ================= */

let roteamento = null;

if (
  isIncoming &&
  operation === 'CREATE' &&
  !fromMe &&
  !isGroup
) {
  if ((messageText && messageText.trim()) || mediaType) {
    roteamento = 'llm';
  } else if (rawZapi.reaction?.value) {
    roteamento = 'reaction';
  }
}

/* ================= OUTPUT ================= */

return [{
  json: {

    // ================= IDs =================

    message_id: messageId,
    conversation_id: conversationId,
    contact_lid: contactLid,
    chat_lid: chatLid,
    sender_lid: senderLid,
    participant_lid: participantLid,
    participant_phone: participantPhone,
    phone: phone,
    connected_phone: connectedPhone,

    // ================= LEAD =================

    lead_name: leadName,
    lead_chat_name: rawZapi.chatName ?? null,
    lead_sender_name: rawZapi.senderName ?? null,
    lead_push_name: rawZapi.pushName ?? null,
    lead_notify_name: rawZapi.notifyName ?? null,
    lead_photo: leadPhoto,
    lead_phone: leadPhone,
    lead_phone_ddd: leadPhoneDdd,
    lead_phone_number: leadPhoneNumber,
    lead_email: null,
    lead_intent: null,

    // ================= EVENTO =================

    tipo_evento: isIncoming ? 'RECEBIDA' : 'STATUS',
    event_type: eventType,
    operation: operation,
    direction: direction,
    origin: 'Z-API',
    roteamento: roteamento,
    notification:             notification,
    notification_params:      notificationParams,
    notification_contact_lid: notificationContactLid,
    is_group_notification:    isGroupNotification,

    from_me: fromMe,
    from_api: rawZapi.fromApi ?? false,

    // ================= FLAGS =================

    is_group: isGroup,
    is_first_interaction: null,
    is_status_reply: rawZapi.isStatusReply ?? false,
    is_edit: rawZapi.isEdit ?? false,
    is_newsletter: rawZapi.isNewsletter ?? false,
    waiting_message: rawZapi.waitingMessage ?? false,
    is_forwarded: rawZapi.forwarded ?? false,
    broadcast: rawZapi.broadcast ?? false,

    // ================= CONTEÚDO =================

    message_text: messageText,
    caption: caption,
    media_type: mediaType,
    media_url: mediaUrl,
    mime_type:      mimeType,
    file_name:      fileName,
    page_count:     pageCount,
    thumbnail_url:  thumbnailUrl,
    ptt:            ptt,
    audio_duration: audioDuration,

    // ================= STATUS =================

    status: status,
    sent_at: sentAt,
    delivered_at: deliveredAt,
    read_at: readAt,

    // ================= CONFIGURAÇÕES =================

    message_expiration_seconds: rawZapi.messageExpirationSeconds ?? null,
    request_method:             rawZapi.requestMethod            ?? null,

    // ================= TIMESTAMPS =================

    first_event_at: eventAt,
    last_update_at: nowSP,
    data_timestamp: rawZapi.momment ?? null,
    expires_at:     rawZapi.expiresAt ?? null,

    // ================= QUOTED =================

    quoted_msg_id: rawZapi.referenceMessageId ?? rawZapi.quotedMsg?.messageId ?? null,
    quoted_msg_body: rawZapi.quotedMsg?.body ?? null,
    quoted_msg: rawZapi.quotedMsg
      ? JSON.stringify(rawZapi.quotedMsg)
      : null,

    // ================= REAÇÃO =================

    reaction_text:       rawZapi.reaction?.value      ?? rawZapi.reactionMessage?.text      ?? null,
    reaction_message_id: rawZapi.reaction?.referencedMessage?.messageId ?? rawZapi.reactionMessage?.messageId ?? null,
    reaction_by:         rawZapi.reaction?.reactionBy  ?? null,    
    // ================= INTERATIVO =================

    selected_button_id: rawZapi.buttonsResponseMessage?.buttonId
      ?? rawZapi.buttonsResponse?.buttonId
      ?? null,

    selected_row_id: rawZapi.listResponseMessage?.selectedRowId
      ?? rawZapi.listResponse?.singleSelectReply?.selectedRowId
      ?? null,

    buttons_response: rawZapi.buttonsResponseMessage
    ? JSON.stringify(rawZapi.buttonsResponseMessage)
    : rawZapi.buttonsResponse
      ? JSON.stringify(rawZapi.buttonsResponse)
      : null,

    list_response: rawZapi.listResponseMessage
    ? JSON.stringify(rawZapi.listResponseMessage)
    : rawZapi.listResponse
      ? JSON.stringify(rawZapi.listResponse)
      : null,

    // ================= CONTATO COMPARTILHADO =================

    contact_display_name: rawZapi.contact?.displayName ?? null,
    contact_vcard:        rawZapi.contact?.vCard        ?? null,
    contact_phones:       rawZapi.contact?.phones
      ? JSON.stringify(rawZapi.contact.phones)
      : null,

    // ================= LOCALIZAÇÃO =================

    location_latitude:  rawZapi.location?.latitude      ?? null,
    location_longitude: rawZapi.location?.longitude     ?? null,
    location_name:      rawZapi.location?.name          ?? null,
    location_address:   rawZapi.location?.address       ?? null,
    location_url:       rawZapi.location?.url           ?? null,

    // ================= POLL =================

    poll_name: rawZapi.pollMessage?.name ?? null,
    poll_options: rawZapi.pollMessage
      ? JSON.stringify(rawZapi.pollMessage.options)
      : null,

    // ================= ANÚNCIO =================

    external_ad_reply: rawZapi.externalAdReply
      ? JSON.stringify(rawZapi.externalAdReply)
      : null,
    ad_source_url:  rawZapi.externalAdReply?.sourceUrl  ?? null,
    ad_title:       rawZapi.externalAdReply?.title       ?? null,
    ad_body:        rawZapi.externalAdReply?.body        ?? null,
    // ================= INFRA =================

    instance_id: rawZapi.instanceId ?? null,
    phone_device: rawZapi.phoneDevice ?? null,

    ids_array: rawZapi.ids
      ? JSON.stringify(rawZapi.ids)
      : null,

    trace_id: traceId,
    span_id:  spanId,

    // ================= AUDITORIA =================

    raw_zapi:    JSON.stringify(rawZapi),
    raw_payload: JSON.stringify(httpInput),
  }
}];

// =======================================
// PREPARAR LOG MSG PRIVADA — COMPLETO
// Passa TODOS os campos do Processar Evento
// =======================================
const data = $('Switch Log Geral').first().json;

// Demanda 318: resolve o texto da mensagem citada (quoted_msg_id), quando existir.
// 'Buscar Mensagem Citada' roda sempre (alwaysOutputData + onError continueRegularOutput,
// mesma licao da demanda 317 - nunca derruba este ramo), fica vazio/nao encontrado na
// maioria dos casos (so ~3% das mensagens sao resposta a algo, e desses ~16% nao acham a
// mensagem original). Nesses casos quoted_msg_body fica null, igual hoje.
let quoted_msg_body = null;
try {
  const found = $('Buscar Mensagem Citada').all();
  const row = (found && found[0] && found[0].json) ? found[0].json : null;
  if (data.quoted_msg_id && row && row.message_id) {
    quoted_msg_body = row.message_text || row.caption || '[midia sem legenda]';
  }
} catch (e) { quoted_msg_body = null; }

// Remove campos internos que não existem na tabela
const { is_autorizado, is_comando_autorizado, ...logData } = data;
logData.quoted_msg_body = quoted_msg_body;

return [{ json: logData }];

// =======================================
// PREPARAR LOG CONTATOS
// Input 0 = evento (do Merge principal)
// Input 1 = contato existente (do Get row(s) CONTATOS)
// =======================================

const allItems = $input.all();

const data = allItems.find(i => i.json.tipo_evento)?.json ?? {};

// candidatos a contato existente: tudo que NAO e o evento em si e tem dado real de linha.
// alwaysOutputData faz cada Get devolver um item VAZIO ({}) quando nao acha nada (nao e copia
// do evento) - {} e "truthy" em JS, entao alem de excluir tipo_evento e preciso exigir 'phone'
// pra nao pegar esse placeholder vazio por engano (achado ao testar a demanda 266).
const candidatos = allItems
  .filter(i => !i.json.tipo_evento && i.json.phone)
  .map(i => i.json);

// prioriza o candidato cujo contact_lid bate com o atual (achado pelo lookup por contact_lid);
// se nao tiver (contact_lid mudou/rotacionou), cai pro achado pelo lookup por phone
// (demanda 266 - contact_lid do WhatsApp e instavel, phone e a identidade real)
const contatoExistente =
  candidatos.find(c => c.contact_lid === data.contact_lid) ??
  candidatos.find(Boolean) ??
  null;

const existe = !!contatoExistente;
const agora = data.last_update_at;

// ================= NOME (nao sobrescrever nome bom por vazio/@lid) =================

function nomeValido(nome, ...identificadores) {
  if (!nome) return false;
  const n = String(nome).trim();
  if (!n) return false;
  return !identificadores.some(id => id && n === String(id).trim());
}

const leadNameFinal = nomeValido(data.lead_name, data.phone, data.contact_lid)
  ? data.lead_name
  : (contatoExistente?.lead_name ?? null);

// ================= TELEFONE (nao sobrescrever numero bom por LID) =================

function phoneValido(phone) {
  if (!phone) return false;
  return !String(phone).includes('@lid');
}

const phoneFinal = phoneValido(data.phone)
  ? data.phone
  : (contatoExistente?.phone ?? data.phone);

const leadPhoneFinal = phoneFinal;
const leadPhoneDddFinal = leadPhoneFinal ? String(leadPhoneFinal).substring(2, 4) : null;
const leadPhoneNumberFinal = leadPhoneFinal ? String(leadPhoneFinal).substring(4) : null;

// ================= IDIOMA =================

function getIdioma(phone) {
  if (!phone) return null;
  if (String(phone).startsWith('55')) return 'pt-BR';
  if (String(phone).startsWith('1')) return 'en-US';
  if (String(phone).startsWith('34')) return 'es-ES';
  return null;
}

// ================= TIMEZONE =================

function getTimezone(phone) {
  if (!phone) return null;
  if (String(phone).startsWith('55')) return 'America/Sao_Paulo';
  if (String(phone).startsWith('1')) return 'America/New_York';
  return null;
}

// ================= PRIMEIRO CONTATO =================

const dataPrimeiroContato =
  contatoExistente?.data_primeiro_contato ?? data.first_event_at;

// ================= CONTADORES =================

let totalRecebidas = data.from_me ? 0 : 1;
let totalEnviadas = data.from_me ? 1 : 0;
let totalInteracoes = 1;
let classificacao = "NOVO";

if (existe) {

  totalRecebidas =
    Number(contatoExistente.total_mensagens_recebidas || 0) +
    (data.from_me ? 0 : 1);

  totalEnviadas =
    Number(contatoExistente.total_mensagens_enviadas || 0) +
    (data.from_me ? 1 : 0);

  totalInteracoes =
    Number(contatoExistente.total_interacoes || 0) + 1;

  classificacao = totalInteracoes > 1 ? "RECORRENTE" : "NOVO";
}

// ================= TIMESTAMPS =================

const criadoEm = contatoExistente?.criado_em ?? agora;
const atualizadoEm = agora;

const _action = existe ? "update" : "create";

// chave pra localizar a linha no UPDATE: o contact_lid JA GRAVADO nela (pode ser o antigo,
// se essa linha foi achada pelo fallback de phone da demanda 266) - nunca o novo contact_lid
// recebido agora, que ainda nao existe em nenhuma linha. Bug achado testando esta demanda:
// filtrar o UPDATE por phone (em vez de por essa chave) colide com constraint unique de
// contact_lid quando o mesmo phone ja tem mais de 1 linha (duplicata historica).
const _matchContactLid = contatoExistente?.contact_lid ?? data.contact_lid;

// ================= OUTPUT =================

return [{
  json: {
    _action,
    _matchContactLid,
    contact_lid: data.contact_lid,
    phone: phoneFinal,
    conversation_id: data.conversation_id,

    lead_name: leadNameFinal,
    lead_chat_name: data.lead_chat_name,
    lead_sender_name: data.lead_sender_name,
    lead_push_name: data.lead_push_name,
    lead_notify_name: data.lead_notify_name,
    lead_photo: data.lead_photo,

    lead_phone: leadPhoneFinal,
    lead_phone_ddd: leadPhoneDddFinal,
    lead_phone_number: leadPhoneNumberFinal,

    lead_email: data.lead_email,
    lead_intent: data.lead_intent,

    idioma: getIdioma(data.participant_phone ?? data.phone),
    timezone: getTimezone(data.participant_phone ?? data.phone),

    data_primeiro_contato: dataPrimeiroContato,
    data_ultimo_contato: agora,

    total_mensagens_recebidas: totalRecebidas,
    total_mensagens_enviadas: totalEnviadas,
    total_interacoes: totalInteracoes,
    classificacao: classificacao,

    criado_em: criadoEm,
    atualizado_em: atualizadoEm,

    tipo_registro: data.is_group ? 'GRUPO' : 'INDIVIDUAL',
    is_group: data.is_group,
    instance_id: data.instance_id
  }
}];

// =======================================
// PREPARAR LOG MSG GRUPOS - COMPLETO
// Passa TODOS os dados sem filtrar
// =======================================
