const leadData = $('Processar Evento').first().json;
let transcricao = '';
try {
  const geminiOutput = $('HTTP Transcrição audio').first().json;
  transcricao = geminiOutput.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
} catch (e) { transcricao = ''; }
return [{ json: { ...leadData, message_text: transcricao || '[áudio sem transcrição]', media_type: leadData.media_type, transcription_text: transcricao || '' } }];

const data = $json;
const AUTORIZADOS = ['5521965185667'];
// Em grupos: phone = ID do grupo; contact_lid = participantPhone (sender real)
const senderPhone = data.contact_lid ?? data.phone ?? '';
const is_grupo_equipe = data.is_group === true;
const is_autorizado = AUTORIZADOS.includes(senderPhone);
const texto = data.message_text ?? '';
const is_comando = texto.trim().startsWith('/');
const is_option_list = !!(data.selected_row_id);
// Privada: autorização normal | Grupo: verifica contact_lid
const is_comando_autorizado =
  !is_grupo_equipe && is_autorizado && (is_comando || is_option_list);
// Flag para roteamento: grupo da equipe + sender autorizado + comando
const is_grupo_pedido = is_grupo_equipe && is_autorizado && is_comando;
return [{ json: { ...data, is_autorizado, is_grupo_equipe, is_comando_autorizado, is_grupo_pedido } }];

const dados = $('ENVIAR PARA LLM').first().json;
const memoriaItems = $('GET Memoria Ativa').all();
const memoria = (memoriaItems && memoriaItems[0]) ? memoriaItems[0].json : null;

// Fases que indicam sessao de pedido aberta (salvas pelo 06-PEDIDOS)
const fasesAtivas = [
  'coleta_specs_pedido',
  'perguntar_pagamento',
  'aguardando_confirmacao_pedido',
  'aguardando_pix'
];

const faseAtual = memoria && memoria.fase_jornada ? memoria.fase_jornada : null;
const statusAtendimento = memoria && memoria.status_atendimento ? memoria.status_atendimento : null;
const origemMemoria = memoria && memoria.origem ? memoria.origem : null;

let estadoConsolidado = null;
if (memoria && memoria.estado_consolidado) {
  try {
    estadoConsolidado = typeof memoria.estado_consolidado === 'string'
      ? JSON.parse(memoria.estado_consolidado)
      : memoria.estado_consolidado;
  } catch(e) {}
}

// Equipe assumiu -> ignora
if (statusAtendimento === 'assumido_humano' || statusAtendimento === 'aguardando_equipe') {
  return [{ json: Object.assign({}, dados, { _destino: 'ignorar', _fase_ativa: faseAtual }) }];
}

// Sessao de pedido aberta (origem=06-pedidos OU fase de pedido)
const temSessaoPedido = fasesAtivas.indexOf(faseAtual) !== -1 || origemMemoria === '06-pedidos';
if (temSessaoPedido) {
  const payload = {
    telefone: dados.phone,
    push_name: dados.lead_push_name || dados.lead_name || 'Cliente',
    fase: faseAtual || 'coleta_specs_pedido',
    mensagem_original: dados.message_text || '',
    message_id: dados.message_id,
    selected_button_id: dados.selected_button_id || null,
    arquivo_url: dados.media_url || null,
    arquivo_tipo: dados.media_type || null,
    arquivo_nome: dados.file_name || null,
    estado_pedido: estadoConsolidado
  };
  return [{ json: Object.assign({}, dados, { _destino: 'pedidos', _fase_ativa: faseAtual, _payload_pedido: payload }) }];
}

// ============================================
// DEMANDA 021 - reconhecimento de palavra-chave
// Sem sessao ativa, mas texto indica intencao de pedido -> entra direto no
// 06-PEDIDOS (fase 'inicio', igual ao payload que a IA ja usa quando
// identifica servico) sem passar pelo JSGRAFICA_ATENDIMENTO_AI.
// Nao reintroduz conversa livre: so aciona o fluxo estruturado de pedidos.
// ============================================
const KEYWORDS_SERVICO = {
  impressao: ['imprimir', 'impressao', 'impressão'],
  xerox: ['xerox', 'copia', 'cópia'],
  foto: ['imprimir foto', 'imprimir fotos', 'revelar foto', 'revelar fotos', 'revelar', 'revelacao', 'revelação', '3x4', '10x15', '7x10', '15x20', '20x29'],
  plastificacao: ['plastificar', 'plastificacao', 'plastificação'],
  encadernacao: ['encadernar', 'encadernacao', 'encadernação', 'espiral'],
  banner: ['banner', 'faixa', 'adesivo'],
  recarga: ['recarga'],
  consulta: ['consulta cpf', 'consulta de cpf', 'consulta serasa', 'consulta de serasa', 'segunda via', '2ª via', '2 via']
};

const textoCliente = String(dados.message_text || '').toLowerCase();
let servicoDetectadoPalavraChave = null;
if (textoCliente.trim()) {
  for (const [servico, palavras] of Object.entries(KEYWORDS_SERVICO)) {
    if (palavras.some(p => textoCliente.includes(p))) {
      servicoDetectadoPalavraChave = servico;
      break;
    }
  }
}

if (servicoDetectadoPalavraChave) {
  const payload = {
    fase: 'inicio',
    telefone: dados.phone,
    push_name: dados.push_name || dados.chat_name || 'Cliente',
    servico_detectado: servicoDetectadoPalavraChave,
    mensagem_original: dados.message_text || '',
    message_id: dados.message_id,
    arquivo_url: dados.media_url || null,
    arquivo_tipo: dados.media_type || null
  };
  return [{ json: Object.assign({}, dados, { _destino: 'pedidos', _fase_ativa: 'inicio', _origem_pedido: 'palavra_chave_021', _payload_pedido: payload }) }];
}

// Sem sessao ativa e sem palavra-chave -> ATENDIMENTO_AI (whitelist decide)
return [{ json: Object.assign({}, dados, { _destino: 'atendimento', _fase_ativa: null }) }];

const original = $('IDENTIFICAR AUTORIZAÇÃO').item.json;
// _has_session sempre false: a tabela 'jsgrafica_config_sessions' nao existe no banco
// (achado ao migrar do JWT hardcoded - o codigo antigo so engolia esse erro em silencio).
// Ver achado registrado na demanda 005 para decisao futura do Edvam/PM.
const _has_session = false;
const _em_onboarding = $('GET Onboarding Sessao').all().length > 0;
return [{ json: { ...original, _has_session, _em_onboarding } }];

const original = $('CHECK SESSAO PEDIDO').first().json;
const rows = $('GET Telefone Autorizado (Fase B)').all();
const autorizado = rows.length > 0 && !!(rows[0].json && rows[0].json.id);

// Demanda 279: a heuristica de palavra-chave da 021 roda ANTES desta checagem dentro do
// CHECK SESSAO PEDIDO e manda _destino='pedidos' pro 06-PEDIDOS (envio desabilitado ha
// semanas, acha 245) sempre que bate uma palavra tipo 'xerox'/'imprimir'/'recarga' etc,
// mesmo sem sessao de pedido real ativa - isso engolia a mensagem em silencio, inclusive
// pra numero autorizado no agente Fase B, que resolve esse caso melhor hoje. So a marca
// _origem_pedido==='palavra_chave_021' identifica esse caminho (sessao de pedido de
// verdade, calculada antes no mesmo node, NUNCA seta essa marca) - reconsiderar so esse
// caso e o fallback padrao ('atendimento'), nunca uma sessao de pedido real.
const eraKeywordAntiga = original._destino === 'pedidos' && original._origem_pedido === 'palavra_chave_021';
const eraAtendimentoFallback = original._destino === 'atendimento';

if (eraKeywordAntiga || eraAtendimentoFallback) {
  const semTexto = !(original.message_text && String(original.message_text).trim());
  const semLegenda = !(original.caption && String(original.caption).trim());
  const midiaSemLegenda = !!original.media_type && semTexto && semLegenda;
  const textoPuro = !original.media_type && !semTexto;
  const elegivelFaseB = midiaSemLegenda || textoPuro;

  if (autorizado && elegivelFaseB) {
    return [{ json: { ...original, _destino: 'agente_fase_b' } }];
  }
  if (eraKeywordAntiga) {
    // Nao autorizado (ou nao elegivel) e so chegou em 'pedidos' por causa da palavra-chave
    // antiga, nao de uma sessao real -> nao deixa cair no 06-PEDIDOS morto, segue pro
    // mesmo caminho de qualquer mensagem sem sessao (ATENDIMENTO_AI, sujeito a whitelist
    // propria dele).
    return [{ json: { ...original, _destino: 'atendimento', _origem_pedido: null } }];
  }
}
return [{ json: original }];

const body = $input.first().json;
const rows = Array.isArray(body) ? body : (body ? [body] : []);
return rows.map(r => ({ json: r }));

// Demanda 299: piloto do agente novo (Caminho C, workflow 297) no mesmo ponto de
// roteamento onde o 206 era chamado (274). So mapeia os nomes de campo que o
// pipeline do 01 usa (phone/message_text) pros nomes que o webhook do agente novo
// espera (telefone/mensagem_texto) - nenhuma logica de elegibilidade nova, a mesma
// checagem de whitelist + Switch Destino de sempre decide quem chega aqui.
// Demanda 317: anexo sem legenda (caption vazio/null) fazia mensagem_texto virar
// string vazia, o agente Caminho C rejeitava com 400 (parametros_invalidos), e o erro
// nao tratado no HTTP Agente Caminho C derrubava a execucao inteira, incluindo o ramo
// de log (Switch Log Geral -> PREPARAR LOG MSG PRIVADA -> MSG PRIVADA), que fica
// irmao deste no mesmo Processar Evento. Fallback final garante nao-vazio, mesma
// convencao ja usada em 'Contexto: Montar Retorno' do workflow 296 (message_text ||
// caption || '[midia sem legenda]').
// Demanda 318: quando a mensagem e resposta a outra (quoted_msg_id), prepende o texto
// da mensagem citada ao contexto que chega pro agente. Resolvido aqui de novo (mesmo
// lookup 'Buscar Mensagem Citada', mesma tabela) porque este ramo (Switch Destino ->
// aqui) e um galho PARALELO ao ramo de log (Switch Log Geral -> PREPARAR LOG MSG
// PRIVADA) - os 2 saem de Processar Evento mas nao compartilham dado computado depois
// dele, cada um precisa da sua propria resolucao.
const d = $json;

let quotedBody = null;
try {
  const found = $('Buscar Mensagem Citada').all();
  const row = (found && found[0] && found[0].json) ? found[0].json : null;
  if (d.quoted_msg_id && row && row.message_id) {
    quotedBody = row.message_text || row.caption || '[midia sem legenda]';
  }
} catch (e) { quotedBody = null; }

const textoBase = d.message_text || d.caption || '[midia sem legenda]';
const mensagem_texto = quotedBody
  ? '[respondendo a: "' + quotedBody + '"] ' + textoBase
  : textoBase;

return [{ json: {
  telefone: d.phone,
  mensagem_texto,
  message_id: d.message_id,
} }];

// Demanda 306: CHECK SESSAO PEDIDO manda qualquer telefone com sessao de pedido
// "ativa" (fase_jornada numa lista de fases ou origem='06-pedidos') direto pro
// 06-PEDIDOS sem checar se esse workflow ainda esta vivo - se estiver morto (caso real
// desde a demanda 303), a execucao falha e o cliente fica sem resposta nenhuma, em
// silencio. Este node so roda quando _destino==='pedidos' (branch true do IF anterior).
// Confirma via API do proprio n8n se o workflow de destino esta ativo ANTES de deixar a
// mensagem seguir pra ele; se nao estiver (ou a propria checagem falhar), trata a
// mensagem exatamente como se nao houvesse sessao de pedido nenhuma - mesma regra de
// elegibilidade que qualquer mensagem sem sessao usa (espelha o bloco
// eraAtendimentoFallback do AJUSTAR DESTINO AGENTE FASE B, que nao roda pra sessao real).
const original = $('AJUSTAR DESTINO AGENTE FASE B').first().json;
const liveness = $json;
const destinoAtivo = !!(liveness && liveness.active === true);

if (destinoAtivo) {
  return [{ json: original }];
}

const rows = $('GET Telefone Autorizado (Fase B)').all();
const autorizado = rows.length > 0 && !!(rows[0].json && rows[0].json.id);
const semTexto = !(original.message_text && String(original.message_text).trim());
const semLegenda = !(original.caption && String(original.caption).trim());
const midiaSemLegenda = !!original.media_type && semTexto && semLegenda;
const textoPuro = !original.media_type && !semTexto;
const elegivelFaseB = midiaSemLegenda || textoPuro;

if (autorizado && elegivelFaseB) {
  return [{ json: { ...original, _destino: 'agente_fase_b', _payload_pedido: null, _destino_morto_fallback: 'WDOixH8LKyh0DDGq' } }];
}
return [{ json: { ...original, _destino: 'atendimento', _origem_pedido: null, _payload_pedido: null, _destino_morto_fallback: 'WDOixH8LKyh0DDGq' } }];

// Demanda 307: protecao contra loop de resposta automatica com away-message/bot do
// cliente (Solfacil, Renegocie Bradesco, Telesefaz e outros achados reais no log). So virou
// risco real depois da demanda 299 (agente novo respondendo de verdade no roteamento real) -
// antes disso nunca existiu volume real de resposta automatica pra formar loop.
let entrada = null;
try { entrada = $('Aplicar Fallback Se Destino Morto').first().json; } catch(e) {}
if (!entrada) {
  try { entrada = $('AJUSTAR DESTINO AGENTE FASE B').first().json; } catch(e) {}
}
const texto = String(entrada.message_text || entrada.caption || '').toLowerCase();

// Camada 1: padroes reais de away-message/resposta automatica, tirados do log real (nao
// inventados) - Solfacil ("mensagem automatica"), Renegocie Bradesco / generic bots
// ("fora do horario de atendimento", "nao estamos disponiveis", "retornaremos"), Telesefaz
// ("sua sessao foi finalizada"). Cuidado de calibracao pedido na demanda: away-message real e
// declarativo, pergunta legitima de cliente tem "?" (ex. "qual o horario de atendimento?",
// achado real 558188603659/558193748247) - por isso qualquer "?" no texto desarma a Camada 1.
const padroesAway = [
  /fora do hor[aá]rio de atendimento/,
  /n[aã]o estamos dispon[ií]ve(l|is)/,
  /mensagem autom[aá]tica/,
  /resposta autom[aá]tica/,
  /retornaremos sua mensagem/,
  /agradecemos sua mensagem[\s\S]{0,80}(hor[aá]rio|segunda|domingo|atendimento)/,
  /sua sess[aã]o foi finalizada/,
];
const temInterrogacao = texto.includes('?');
const bateuPadraoAway = !temInterrogacao && texto.trim().length > 0 && padroesAway.some(re => re.test(texto));

let loopDetectado = bateuPadraoAway;
let motivo = bateuPadraoAway ? 'padrao_away_message_conhecido' : null;

// Camada 2: contador de seguranca - mesmo sem bater nenhum padrao conhecido, se o sistema ja
// mandou 2+ respostas automaticas (ia/sistema) pro mesmo telefone nos ultimos 10 minutos, a
// proxima seria a 3a seguida - para e escala em vez de continuar (simplificacao deliberada de
// "sem sinal de intencao humana real": o numero concreto que a propria demanda 307 propos como
// exemplo, 3 em 10min, e o criterio testavel adotado).
if (!loopDetectado) {
  // Este node httpRequest faz auto-split de um array JSON em multiplos itens n8n (1 item
  // por linha real), diferente do padrao de outro node PostgREST desta mesma conta (demanda
  // 281, que NAO faz esse split) - confirmado ao vivo, nao presumido igual por semelhanca.
  // Quando 0 linhas batem, alwaysOutputData forca 1 item com json vazio {} (nao um array
  // vazio) - precisa distinguir isso de "1 linha real".
  const contarItems = $('Contar Envios Automaticos Recentes').all();
  const placeholderVazio = contarItems.length === 1 && contarItems[0].json && Object.keys(contarItems[0].json).length === 0;
  const qtd = placeholderVazio ? 0 : contarItems.length;

  // Demanda 309, achado real no 1o dia do piloto: a contagem bruta sozinha bloqueou uma
  // conversa real (cliente mandou "Benca"/"Tudo bem sim"/"Nao da pra editar ne?", 3 mensagens
  // DIFERENTES, cada uma com resposta real distinta - nao e loop nenhum, e o limiar de 2 vindo
  // da demanda 307 bloqueou a 3a mensagem so por contagem). So considera loop se, ALEM da
  // contagem, as ultimas mensagens DO CLIENTE forem repetidas/identicas entre si - essa e a
  // assinatura real de bot/away-message batendo (texto igual toda vez), nao de conversa humana
  // variada. Limiar de contagem tambem subiu de 2 pra 3 (backstop de frequencia bruta pra caso
  // extremo, mas a decisao real agora depende da repeticao de conteudo, nao so da contagem).
  if (qtd >= 3) {
    const inboundItens = $('Buscar Mensagens Cliente Recentes').all();
    const inboundPlaceholderVazio = inboundItens.length === 1 && inboundItens[0].json && Object.keys(inboundItens[0].json).length === 0;
    const textosInbound = inboundPlaceholderVazio ? [] : inboundItens.map(i => String((i.json && i.json.message_text) || '').trim().toLowerCase());
    const semVariedade = textosInbound.length >= 2 && new Set(textosInbound).size === 1;
    if (semVariedade) {
      loopDetectado = true;
      motivo = 'contador_seguranca_estourado';
    }
  }
}

if (loopDetectado) {
  return [{ json: { ...entrada, _destino: 'ignorar', _loop_automatico_detectado: true, _loop_automatico_motivo: motivo } }];
}
return [{ json: entrada }];

// Demanda 307: "Marcar Sessao Para Revisao Humana" e um httpRequest - a resposta da API
// (nao o payload original) vira o novo $json, o que apagaria o _destino:'ignorar' que
// "Detectar Loop Resposta Automatica" decidiu, deixando a mensagem cair sem querer no
// fallback de atendimento normal (o oposto do que a Camada 2 pede: "sem mandar mais
// nenhuma mensagem sozinho"). Restaura explicitamente o payload correto por referencia
// nomeada, mesma classe de bug ja corrigida 2x antes nesta mesma demanda.
return [{ json: $('Detectar Loop Resposta Automatica').first().json }];

// Demanda 318 (Fix B): mesmo padrao de 'Converter para base64' (audio) e de
// 'Converter Mídia Base64' do 206, mas com try/catch explicito - o 206 NAO tinha
// tratamento de erro aqui (gap ja identificado antes de copiar, mesma licao da
// demanda 317: nunca deixar um node novo sem rede de seguranca). Qualquer falha
// (download sem binario, buffer vazio, etc.) produz _media_base64 null em vez de
// derrubar a execucao - o node seguinte (Gemini) e o de parse tratam esse caso e
// caem no fallback '[midia sem legenda]'.
try {
  const item = $input.first();
  const binaryKey = item.binary ? Object.keys(item.binary)[0] : null;
  if (!binaryKey) {
    return [{ json: { ...item.json, _media_base64: null, _media_mime: null } }];
  }
  const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
  const base64 = buffer.toString('base64');
  const mimeType = (item.binary[binaryKey].mimeType || item.json.mime_type || 'application/octet-stream').split(';')[0];
  return [{ json: { ...item.json, _media_base64: base64, _media_mime: mimeType } }];
} catch (e) {
  const fallbackJson = ($input.first() && $input.first().json) ? $input.first().json : {};
  return [{ json: { ...fallbackJson, _media_base64: null, _media_mime: null, _erro_conversao_midia: String((e && e.message) || e) } }];
}

// Demanda 318 (Fix B): mesmo padrao de parse do 206 ('Parsear Resposta Gemini'), mas
// formatando uma frase legivel (pro agente E pro humano lendo o Inbox depois) em vez de
// so devolver o JSON cru, e escrevendo o resultado em message_text pra chegar ate
// 'Preparar Payload Agente Caminho C' pelo mesmo caminho que a transcricao de audio ja
// usa (ENVIAR PARA LLM -> ... -> Switch Destino). Qualquer falha em qualquer etapa
// anterior (download, conversao base64, chamada Gemini) cai no MESMO fallback ja usado
// em toda a base ('[midia sem legenda]') - nunca derruba a execucao (licao da 317).
const original = $('Processar Evento').first().json;

let resultado = '[midia sem legenda]';
try {
  const conv = $('Converter Mídia Base64 (Imagem/Doc)').first().json;
  const geminiOut = $json;
  if (conv && conv._media_base64 && geminiOut && geminiOut.candidates) {
    const texto = (geminiOut.candidates[0]?.content?.parts || []).map(p => p.text || '').join('');
    const m = texto.match(/\{[\s\S]*\}/);
    if (m) {
      const parsed = JSON.parse(m[0]);
      const tipo = parsed.tipo_midia === 'pdf' ? 'documento PDF' : 'imagem';
      const paginas = parsed.numero_paginas ? ` (${parsed.numero_paginas} pagina${parsed.numero_paginas > 1 ? 's' : ''})` : '';
      const detectado = parsed.produto_ou_valor_detectado ? `, aparenta ser: ${parsed.produto_ou_valor_detectado}` : '';
      const classif = parsed.classificacao === 'documento_obvio' ? '' : ' (conteudo ambiguo, confirmar com o cliente)';
      resultado = `[cliente enviou ${tipo}${paginas} sem legenda${detectado}${classif}]`;
    }
  }
} catch (e) { resultado = '[midia sem legenda]'; }

return [{ json: { ...original, message_text: resultado, _gemini_analise_midia: resultado } }];

// Demanda 321 - novo gate: bloqueia a IA (Caminho C) quando um humano ja esta
// atendendo esse telefone de verdade, ou quando a propria IA ja escalou esse
// telefone antes (status 'escalado') e ainda nao foi liberado/resolvido. Contato
// novissimo (sem linha em jsgrafica_contatos) ou qualquer outro estado (aberto /
// resolvido / em_atendimento com atendente='Agente Atendimento') NAO bloqueia -
// segue normal pro Switch Destino, igual hoje.
//
// O node anterior (httpRequest + alwaysOutputData, mesmo padrao ja comprovado
// nesta instancia hoje - demandas 307/309/314) pode devolver o resultado do
// PostgREST de 2 formas diferentes dependendo do node (achado documentado em
// 'Detectar Loop Resposta Automatica'/307: as vezes 1 item com o array bruto no
// json, as vezes auto-split em 1 item por linha, com item unico de json vazio {}
// quando 0 linhas batem). Tratamos os dois formatos aqui, sem presumir qual esta
// ativo - nunca deixa a execucao quebrar por falta de dado quando o contato e novo.
const items = $input.all();
let rows = [];
for (const it of items) {
  const j = it.json;
  if (Array.isArray(j)) {
    rows = rows.concat(j);
  } else if (j && Object.keys(j).length > 0) {
    rows.push(j);
  }
}
const contato = rows.length > 0 ? rows[0] : null;

// A entrada original (telefone, _destino ja calculado por AJUSTAR DESTINO AGENTE
// FASE B + possivel override de Detectar Loop Resposta Automatica) precisa vir de
// qualquer um dos 2 nodes que alimentam este ponto - so um deles roda por
// execucao. Mesmo padrao de dupla tentativa ja usado em 'Detectar Loop Resposta
// Automatica' (demanda 307).
let entrada = null;
try { entrada = $('Restaurar Entrada Apos Marcar').first().json; } catch (e) {}
if (!entrada) {
  try { entrada = $('Loop Automatico Estourou?').first().json; } catch (e) {}
}
if (!entrada) entrada = {};

const statusAtendimento = contato ? contato.status_atendimento : null;
const atendente = contato ? contato.atendente : null;

const humanoAtendendo = statusAtendimento === 'em_atendimento' && !!atendente && atendente !== 'Agente Atendimento';
const iaJaEscalou = statusAtendimento === 'escalado';
const deveBloquear = (humanoAtendendo || iaJaEscalou) && entrada._destino === 'agente_fase_b';

if (deveBloquear) {
  return [{ json: { ...entrada, _destino: 'ignorar', _bloqueado_status_atendimento: true, _bloqueado_motivo: humanoAtendendo ? 'humano_atendendo' : 'ia_ja_escalou' } }];
}
return [{ json: entrada }];

// Demanda 325: cortesia de uma so vez por janela de cooldown quando a conversa
// esta parada em 'escalado' (ninguem no Admin resolveu ainda) e o cliente manda
// mensagem nova, que ate hoje caia no dead-end 'ignorar' sem nenhuma resposta,
// nem confirmacao de recebimento. Cooldown gravado em
// jsgrafica_agente_teste_sessoes.dados_extra (mesmo jsonb ja usado pra
// motivo_escalonamento, sem precisar de coluna nova) - le-antes-de-escrever dentro
// da mesma execucao, aceitavel pro tamanho da janela (nao e cenario de alta
// concorrencia, o mesmo telefone escalado nao manda 2 mensagens no mesmo instante).
const COOLDOWN_MINUTOS = 45;

const items = $input.all();
let rows = [];
for (const it of items) {
  const j = it.json;
  if (Array.isArray(j)) {
    rows = rows.concat(j);
  } else if (j && Object.keys(j).length > 0) {
    rows.push(j);
  }
}
const sessao = rows.length > 0 ? rows[0] : null;
const dadosExtraAtual = (sessao && sessao.dados_extra) ? sessao.dados_extra : {};

const ultimoEnvioIso = dadosExtraAtual.cortesia_dead_end_enviada_em || null;
let dentroDoCooldown = false;
if (ultimoEnvioIso) {
  const minutosDesde = (Date.now() - new Date(ultimoEnvioIso).getTime()) / 60000;
  dentroDoCooldown = minutosDesde < COOLDOWN_MINUTOS;
}

const entrada = $('Cortesia: Motivo Foi Escalado?').first().json;

return [{ json: {
  ...entrada,
  _cortesia_pode_enviar: !dentroDoCooldown,
  _cortesia_dados_extra_novo: { ...dadosExtraAtual, cortesia_dead_end_enviada_em: new Date().toISOString() },
} }];

// Demanda 325: mesmo padrao de calculo de _zapi_base/_zapi_token ja usado em
// 'Montar Envio Z-API' do workflow 297 (config.zapi_url sem o ultimo segmento de
// path vira a base, client_token vai no header client-token) - reaproveitado aqui
// isolado porque o workflow 01 nunca teve nenhum node de envio Z-API ate hoje (so
// loga/roteia, nunca manda mensagem sozinho).
const items = $input.all();
let rows = [];
for (const it of items) {
  const j = it.json;
  if (Array.isArray(j)) {
    rows = rows.concat(j);
  } else if (j && Object.keys(j).length > 0) {
    rows.push(j);
  }
}
const config = rows.length > 0 ? rows[0] : {};

const entrada = $('Cortesia: Pode Enviar?').first().json;

const TEXTO_CORTESIA = "Isso já tá com a equipe, só um minutinho que já te respondo por aqui 😊";

return [{ json: {
  ...entrada,
  _cortesia_texto: TEXTO_CORTESIA,
  _zapi_base: config.zapi_url ? config.zapi_url.replace(/\/[^/]+$/, '') : null,
  _zapi_token: config.client_token || null,
} }];
